import{_ as a,o as d,c as e,ah as r}from"./chunks/framework.Yx0DUrwu.js";const p=JSON.parse('{"title":"抗原识别与抗原提呈","description":"","frontmatter":{},"headers":[],"relativePath":"biology/antigen-recognition-presentation.md","filePath":"biology/antigen-recognition-presentation.md","lastUpdated":1787830595000}'),o={name:"biology/antigen-recognition-presentation.md"};function n(i,t,s,c,l,h){return d(),e("div",null,[...t[0]||(t[0]=[r('<h1 id="抗原识别与抗原提呈" tabindex="-1">抗原识别与抗原提呈 <a class="header-anchor" href="#抗原识别与抗原提呈" aria-label="Permalink to &quot;抗原识别与抗原提呈&quot;">​</a></h1><p>适应性免疫的精细识别依赖两套受体逻辑：B 细胞受体（BCR）和抗体可以直接识别天然抗原表面；T 细胞受体（TCR）通常识别肽-MHC 复合物。抗原提呈则把细胞内外蛋白加工成 T 细胞能读懂的信号 [1]。</p><h2 id="bcr-和-tcr-的差异" tabindex="-1">BCR 和 TCR 的差异 <a class="header-anchor" href="#bcr-和-tcr-的差异" aria-label="Permalink to &quot;BCR 和 TCR 的差异&quot;">​</a></h2><table tabindex="0"><thead><tr><th>维度</th><th>BCR / 抗体</th><th>TCR</th></tr></thead><tbody><tr><td>识别对象</td><td>天然蛋白、糖、脂质或复杂构象表面。</td><td>多数为 MHC 呈递的抗原肽。</td></tr><tr><td>抗原形式</td><td>可识别可溶或细胞表面抗原。</td><td>需要抗原提呈细胞（APC）或靶细胞表面的肽-MHC 复合物。</td></tr><tr><td>后续效应</td><td>分化为浆细胞、产生抗体、形成记忆 B 细胞。</td><td>分化为 CD4 辅助 T 细胞、CD8 细胞毒性 T 细胞、Treg 等效应群。</td></tr><tr><td>单细胞线索</td><td><code>MS4A1</code>, <code>CD79A</code>, <code>CD79B</code>, <code>IGH*</code>, <code>JCHAIN</code>。</td><td><code>CD3D</code>, <code>CD3E</code>, <code>TRAC</code>, <code>CD4</code>, <code>CD8A</code>, 克隆型。</td></tr></tbody></table><h2 id="mhc-i-和-mhc-ii" tabindex="-1">MHC-I 和 MHC-II <a class="header-anchor" href="#mhc-i-和-mhc-ii" aria-label="Permalink to &quot;MHC-I 和 MHC-II&quot;">​</a></h2><table tabindex="0"><thead><tr><th>通路</th><th>抗原来源</th><th>表达细胞</th><th>识别细胞</th><th>关键意义</th></tr></thead><tbody><tr><td>MHC-I</td><td>细胞质蛋白、病毒蛋白、肿瘤抗原</td><td>几乎所有有核细胞</td><td>CD8 T 细胞</td><td>让 CD8 T 细胞监视细胞内部异常。</td></tr><tr><td>MHC-II</td><td>胞吞、吞噬、自噬来源的蛋白</td><td>专职抗原提呈细胞</td><td>CD4 T 细胞</td><td>让 CD4 T 细胞感知外源病原和组织抗原。</td></tr><tr><td>交叉提呈</td><td>外源抗原进入 MHC-I 通路</td><td>树突细胞</td><td>CD8 T 细胞</td><td>让树突细胞激活初始 CD8 T 细胞。</td></tr><tr><td>非经典提呈</td><td>脂质或微生物代谢物</td><td>CD1、MR1 等</td><td>NKT、MAIT 等</td><td>连接屏障组织、微生物群和快速 T 样应答。</td></tr></tbody></table><h2 id="抗原加工路线" tabindex="-1">抗原加工路线 <a class="header-anchor" href="#抗原加工路线" aria-label="Permalink to &quot;抗原加工路线&quot;">​</a></h2><div class="flow-strip"><span>内源蛋白</span><span>蛋白酶体切割</span><span>TAP 转运入 ER</span><span>MHC-I 装载</span><span>外源蛋白</span><span>内吞体/溶酶体降解</span><span>MHC-II 肽交换</span><span>CD4/CD8 T 细胞识别</span></div><h2 id="单细胞中的抗原提呈细胞判断" tabindex="-1">单细胞中的抗原提呈细胞判断 <a class="header-anchor" href="#单细胞中的抗原提呈细胞判断" aria-label="Permalink to &quot;单细胞中的抗原提呈细胞判断&quot;">​</a></h2><div class="check-grid"><article><strong>抗原呈递能力</strong><span>看 `HLA-DRA`, `HLA-DRB1`, `HLA-DPA1`, `HLA-DPB1`, `B2M`, `HLA-A/B/C` 等，不只看细胞类型名字。</span></article><article><strong>成熟树突细胞</strong><span>抗原摄取、迁移、共刺激和细胞因子程序共同决定 T 细胞启动能力。</span></article><article><strong>B 细胞作为抗原提呈细胞</strong><span>B 细胞可高效提呈其 BCR 捕获的抗原，尤其在 T-B 连锁识别中重要。</span></article><article><strong>肿瘤微环境</strong><span>MHC-I 降低、抗原提呈细胞缺失或共刺激不足都可能削弱 T 细胞介导的杀伤。</span></article></div><h2 id="自检问题" tabindex="-1">自检问题 <a class="header-anchor" href="#自检问题" aria-label="Permalink to &quot;自检问题&quot;">​</a></h2><ol><li>为什么 CD8 T 细胞通常读 MHC-I，而 CD4 T 细胞通常读 MHC-II？</li><li>交叉提呈解决了什么免疫学问题？</li><li>BCR 识别抗原和 TCR 识别抗原的本质差异是什么？</li><li>在单细胞数据中，为什么 HLA 高表达不一定意味着有效 T 细胞启动？</li></ol><h2 id="参考资料" tabindex="-1">参考资料 <a class="header-anchor" href="#参考资料" aria-label="Permalink to &quot;参考资料&quot;">​</a></h2><p>[1] Murphy, K. &amp; Weaver, C. <em>Janeway&#39;s Immunobiology</em>. 9th ed. Garland Science (2017). 中文版：《詹韦免疫生物学：原书第九版》，科学出版社，2022。</p>',14)])])}const T=a(o,[["render",n]]);export{p as __pageData,T as default};
